// Package lockfile reads GitHub Actions workflow dependency lockfiles.
// https://docs.github.com/en/enterprise-cloud@latest/actions/concepts/security/workflow-dependency-lockfiles
package lockfile

import (
	"errors"
	"fmt"
	"io/fs"
	"path/filepath"
	"slices"

	"github.com/spf13/afero"
	"gopkg.in/yaml.v3"
)

// Path is the path of the lockfile from the repository root.
const Path = ".github/workflows/actions.lock"

// Lockfile is a workflow dependency lockfile generated by `gh actions-lock`.
type Lockfile struct {
	Version string
	// Workflows maps a workflow file path to the action references the workflow uses.
	Workflows map[string][]string
	// Dependencies maps an action reference to the commit it is locked to.
	Dependencies map[string]*Dependency
}

type Dependency struct {
	Ref     string
	Commit  string
	OwnerID int64 `yaml:"owner_id"`
	RepoID  int64 `yaml:"repo_id"`
}

// Read reads the lockfile. It returns nil without an error if the lockfile doesn't exist.
func Read(afs afero.Fs) (*Lockfile, error) {
	b, err := afero.ReadFile(afs, Path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, nil //nolint:nilnil
		}
		return nil, fmt.Errorf("read a lockfile: %w", err)
	}
	lf := &Lockfile{}
	if err := yaml.Unmarshal(b, lf); err != nil {
		return nil, fmt.Errorf("parse a lockfile as YAML: %w", err)
	}
	return lf, nil
}

// Locked reports whether the action reference uses is locked for the workflow.
func (lf *Lockfile) Locked(workflowFilePath, uses string) bool {
	if !slices.Contains(lf.Workflows[filepath.ToSlash(workflowFilePath)], uses) {
		return false
	}
	_, ok := lf.Dependencies[uses]
	return ok
}
